// Value Object for card number with built-in security
class CardNumber {
  private readonly _value: string;

  constructor(value: string) {
    if (value.length !== 16) {
      throw new Error('Invalid card number length');
    }
    this._value = value;
  }

  get lastFour(): string {
    return this._value.slice(-4);
  }

  // Never expose full number
  get masked(): string {
    return `****-****-****-${this.lastFour}`;
  }

  // For payment processing only
  getRawValue(): string {
    return this._value;
  }
}
